56:export async function lastSuccessTime(gh, repo, workflowFile = SCHEDULER_WORKFLOW_FILE) {
57-  // SCHEDULE events only. The watermark's meaning is "the last time every due slot
58-  // was evaluated", and since forced runs evaluate ONLY their forced tasks (#749),
59-  // a hand-started run can no longer stand as that claim. Counting one would
60-  // swallow any slot that fell between the last cron run and the button press —
61-  // evaluated by nobody, yet behind the watermark. The cost runs the other way and
62-  // is safe: a plain manual run's work is re-evaluated by the next cron, where the
63-  // (task, slot) exactly-once dispatch guard and the workers' own idempotence make
64-  // the repeat a no-op.
65-  const { status, json } = await gh(`/repos/${repo}/actions/workflows/${workflowFile}/runs?status=success&event=schedule&per_page=1`);
66-  if (status !== 200) throw new Error(`run ledger unreadable: GET workflow runs returned ${status}`);
67-  const run = json?.workflow_runs?.[0];
68-  if (!run) return null;
69-  const at = run.run_started_at || run.created_at;
70-  // A run record exists, so this repo is demonstrably not a fresh adoption —
71-  // saying null here would be the same wrong claim by a narrower route.
72-  if (!at) throw new Error('run ledger unreadable: newest successful run carries no timestamp');
73-  return at;
74-}
75-
76-// The repo slug (owner/name) and default branch the workflow runs against, from
77-// the Actions environment. `GITHUB_REPOSITORY` is always set in a workflow;
78-// `GITHUB_REF_NAME` is the branch for a scheduled/dispatch run on the default branch.
79-export function actionRepoContext(env = process.env) {
80-  return {
81-    repo: env.GITHUB_REPOSITORY || null,
82-    defaultBranch: env.GITHUB_REF_NAME || 'main',
83-  };
84-}

