1	// The task's PARAMETERS — the one place that decides what this run is, and the only
2	// module either half consults for it.
3	//
4	// WHY PARAMETERS AT ALL. This task used to be one thing: a weekly fleet-wide scan that
5	// converged an issue per member whose SHAPE fingerprinted packs its declaration did not
6	// carry. That is a discovery loop, and it answers only the question "what might a member
7	// want". The owner's other question — "put THIS pack on THESE repos with THIS config,
8	// now" — has the same second stage (adopt-pack against a member, one reviewed PR) and a
9	// completely different first stage: nothing is being suspected, because the answer was
10	// already decided. Parameterising the task is what lets one task carry both, instead of a
11	// second task that would duplicate the agent stage to change the work list's provenance.
12	//
13	// NO DEFAULTS, DELIBERATELY. Neither parameter has a fallback here: an unset one is an
14	// error that fails the run before anything is read or written. Both call sites therefore
15	// state what they want, in full:
16	//
17	//   the weekly run   task.mjs's `prework` command line — `--scan-for-needed-packs=true
18	//                    --repos=all-covered-members`, which is the declaration saying, in the
19	//                    file a reader opens first, exactly what the cadence does.
20	//   a FORCED run     a hand-created item's Context (`CLAUDINITE_CONTEXT`, parsed by
21	//                    the pack's param-bag.mjs), which the prework subprocess inherits.
22	//                    Context parameters WIN over the command line, because the whole
23	//                    point of a hand-created item is to run this task as something
24	//                    other than what the weekly declaration says.
25	//
26	// A default would defeat both: the reason the fleet-wide scan is safe is that it is
27	// spelled out where it is scheduled, and the reason a force is safe is that every repo it
28	// touches was typed by a human. `all-covered-members` is a KEYWORD, not a default — the
29	// weekly run sends it explicitly, so no call site can reach the fleet by omission.
30	//
31	// Pure: parsing and validation only, no I/O, no environment reads. The worker hands it
32	// `argv` and the parsed override bag; every rejection is a thrown Error whose message is
33	// the fix.
34	
35	// The literal a caller sends to mean "every covered, non-dormant member under the
36	// configured owner" — the scan's fleet-wide scope, said out loud.
37	export const ALL_MEMBERS = 'all-covered-members';
38	
39	// A list value is SPACE-separated, never comma-separated: the parameter bag splits keys
40	// on commas (`param-bag.mjs`), so a comma inside a value would silently become a second,
41	// unknown key. Both call sites use the same splitter so the two are never subtly
42	// different.
43	const list = (raw) => String(raw ?? '').split(/\s+/).map((s) => s.trim()).filter(Boolean);
44	
45	// `--flag=value` command-line pairs, the form task.mjs's `prework` string uses. Anything
46	// not in that shape is a typo worth failing on rather than ignoring.
47	export function parseArgv(argv = []) {
48	  const out = {};
49	  for (const arg of argv) {
50	    const m = /^--([a-z][a-z0-9-]*)=(.*)$/.exec(String(arg));
51	    if (!m) throw new Error(`unrecognised prework argument \`${arg}\` — expected \`--<name>=<value>\``);
52	    out[m[1]] = m[2];
53	  }
54	  return out;
55	}
56	
57	// `true` / `false` and nothing else. A boolean parameter that accepted "1", "yes" or the
58	// mere presence of the key would make `SCAN_FOR_NEEDED_PACKS=false` read as on — the one
59	// misreading that turns a targeted force into a fleet-wide sweep.
60	function bool(name, raw) {
61	  const v = String(raw).trim().toLowerCase();
62	  if (v === 'true') return true;
63	  if (v === 'false') return false;
64	  throw new Error(`${name} must be exactly \`true\` or \`false\` (got \`${raw}\`)`);
65	}
66	
67	// `<packId>.<key>=<value>` — the shape both the config and the answer entries take in the
68	// override bag, where a comma cannot appear in a value. Keys may be dotted
69	// (`pack.a.b=v` → `{ a: { b: 'v' } }`) so a nested config is expressible without JSON.
70	function entry(kind, raw) {
71	  const text = String(raw).trim();
72	  const eq = text.indexOf('=');
73	  if (eq === -1) throw new Error(`${kind} entry \`${raw}\` is not \`<pack-id>.<key>=<value>\``);
74	  const path = text.slice(0, eq).trim();
75	  const value = text.slice(eq + 1).trim();
76	  const dot = path.indexOf('.');
77	  if (dot <= 0 || dot === path.length - 1) throw new Error(`${kind} entry \`${raw}\` names no pack — expected \`<pack-id>.<key>=<value>\``);
78	  if (!value) throw new Error(`${kind} entry \`${raw}\` has an empty value`);
79	  return { pack: path.slice(0, dot), keyPath: path.slice(dot + 1).split('.'), value };
80	}
81	
82	// Fold `<pack>.<dotted.key>=<value>` entries into `{ [pack]: { …nested } }`. Collisions
83	// throw: a run whose config depends on which of two entries was applied last is one whose
84	// declaration nobody can predict from the button that started it.
85	function foldEntries(kind, raws) {
86	  const out = {};
87	  for (const raw of raws) {
88	    const { pack, keyPath, value } = entry(kind, raw);
89	    let node = (out[pack] ??= {});
90	    for (const key of keyPath.slice(0, -1)) {
91	      node[key] ??= {};
92	      if (typeof node[key] !== 'object') throw new Error(`${kind} entries conflict on \`${pack}.${keyPath.join('.')}\``);
93	      node = node[key];
94	    }
95	    const leaf = keyPath[keyPath.length - 1];
96	    if (leaf in node) throw new Error(`${kind} entries conflict on \`${pack}.${keyPath.join('.')}\``);
97	    node[leaf] = value;
98	  }
99	  return out;
100	}
101	
102	// Every override key whose name starts with `prefix` — `PACK_CONFIG`, `PACK_CONFIG_2`,
103	// `PACK_CONFIG_store`, … . The bag is a flat map with one value per key, so a run that
104	// sets two config keys on one pack needs two DISTINCT keys; the suffix is free-form
105	// because its only job is to make them distinct. Sorted, so the report and any error
106	// name them in a stable order.
107	function prefixed(overrides, prefix) {
108	  return Object.keys(overrides).filter((k) => k.startsWith(prefix)).sort().map((k) => overrides[k]);
109	}
110	
111	// The whole contract: what this run is, resolved from the two call sites.
112	//
113	//   { scan, repos, allMembers, addPacks, packConfig, packAnswers, forced }
114	//
115	// `repos` is null when `allMembers` is true — a caller that wants the fleet gets the
116	// keyword's meaning, never a list it could accidentally treat as complete.
117	export function parseParams({ argv = [], overrides = {} } = {}) {
118	  const cli = parseArgv(argv);
119	  const pick = (flag, key) => (overrides[key] !== undefined ? overrides[key] : cli[flag]);
120	
121	  const rawScan = pick('scan-for-needed-packs', 'SCAN_FOR_NEEDED_PACKS');
122	  if (rawScan === undefined) {
123	    throw new Error('scan_for_needed_packs was not sent. This parameter has no default: the weekly run '
124	      + 'sends `--scan-for-needed-packs=true` from task.mjs, and a forced run sends '
125	      + '`--context "SCAN_FOR_NEEDED_PACKS=false"` when the item is created.');
126	  }
127	  const scan = bool('scan_for_needed_packs', rawScan);
128	
129	  const rawRepos = pick('repos', 'REPOS');
130	  if (rawRepos === undefined || !list(rawRepos).length) {
131	    throw new Error(`repos was not sent. This parameter has no default: send \`${ALL_MEMBERS}\` for the whole `
132	      + 'fleet (what the weekly run sends) or a space-separated list of repo names (bare `Name` or '
133	      + '`owner/Name`). Space-separated, not comma-separated — the parameter bag splits keys on commas.');
134	  }
135	  const names = list(rawRepos);
136	  const allMembers = names.includes(ALL_MEMBERS);
137	  if (allMembers && names.length > 1) {
138	    throw new Error(`repos mixes \`${ALL_MEMBERS}\` with explicit names (${names.join(', ')}) — send one or the other`);
139	  }
140	
141	  const addPacks = list(pick('add-packs', 'ADD_PACKS'));

