1	// The machine-readable records a task's execution leaves in an Actions log
2	// (skill-usage-metrics DESIGN §4.2), and the parsers that read them back.
3	//
4	// TWO FAMILIES, ONE OF THEM HISTORICAL. `claudinite-task-run` was the SLOT
5	// scheduler's own line, one per due task per run; the slot scheduler is retired
6	// (#974) and nothing writes that line any more. The parser stays, and only the
7	// parser: Actions logs from before the retirement are still inside their retention
8	// window, and the usage fold still counts them. Nothing new should be taught this
9	// shape — `claudinite-task-exec` below is the live record.
10	//
11	// The counts these produce are exact within the Actions log retention window, and
12	// that is worth stating next to the capture-derived counts they land beside.
13	
14	// The five things a slot scheduler run could do with a due task. One name per
15	// outcome, used verbatim as the counter key in the aggregate, so there is no
16	// mapping table between "what the run said" and "what the fold counted" to drift.
17	export const TASK_RUN_OUTCOMES = Object.freeze([
18	  // A dispatch issue was filed: an executor session runs this task with an agent.
19	  'agent',
20	  // The task ran with NO agent — an `agent_model: none` task (prework is the
21	  // whole task), or an agentful one whose prework requested no agent phase.
22	  'prework',
23	  // Due, but its precondition said there was nothing to do.
24	  'skipped',
25	  // Its prework failed; the run converged the task to a needs-human issue.
26	  'failed',
27	  // Due and past its precondition, but no NEW agent run started: this slot was
28	  // already dispatched (exactly-once), an earlier dispatch is still open
29	  // (at-most-one-open), or another task claimed the run exclusively. Work that
30	  // was wanted and did not happen this run.
31	  'deferred',
32	]);
33	
34	// An empty per-task counter row — every outcome present, zeros included, so a row's
35	// shape never depends on which outcomes a task happened to hit.
36	export const emptyTaskRun = () => Object.fromEntries(TASK_RUN_OUTCOMES.map((o) => [o, 0]));
37	
38	// The line format. `v1` is the shape's version: a reader that meets a `v2` line
39	// knows it is looking at something it was not written for, instead of silently
40	// half-parsing it.
41	export const TASK_RUN_TAG = 'claudinite-task-run';
42	const VERSION = 'v1';
43	
44	// Actions stamps every log line with its own timestamp before the command's output,
45	// so the parse tolerates that prefix — without it, a fetched log reads as having
46	// printed nothing at all.
47	const LINE_RE = new RegExp(
48	  String.raw`^(?:\S+\s+)?${TASK_RUN_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
49	);
50	
51	// One line → `{ pack, task, slotId, outcome }`, or null for anything that is not a
52	// record of this version. Deliberately strict: an unknown outcome word is NOT a
53	// record, because counting it would mint a counter key nothing ever reads.
54	// `preprocess` is the pre-rename word for the prework outcome (2026-08-06);
55	// runs logged before the rename still parse, normalized to the canonical word.
56	export function parseTaskRun(line) {
57	  const m = LINE_RE.exec(line);
58	  if (!m) return null;
59	  const [, pack, task, slotId, word] = m;
60	  const outcome = word === 'preprocess' ? 'prework' : word;
61	  if (!TASK_RUN_OUTCOMES.includes(outcome)) return null;
62	  return { pack, task, slotId, outcome };
63	}
64	
65	// Every record in one job log. The log is the whole job's output — this picks its
66	// own lines out of it and ignores everything else.
67	export function parseTaskRuns(text) {
68	  const out = [];
69	  for (const line of String(text ?? '').split('\n')) {
70	    const rec = parseTaskRun(line);
71	    if (rec) out.push(rec);
72	  }
73	  return out;
74	}
75	
76	// --- executor-side execution records ------------------------------------------
77	// The scheduler records what it DID with a due task (above); these record what an
78	// EXECUTOR SESSION did with the dispatch it ran. Printed by executor-side code
79	// (resolve-dispatch on a terminal verdict, record-exec.mjs at convergence), they
80	// land in the session transcript, ride to the conversation-logs branch with the
81	// executor's capture step, and the usage fold counts them deterministically —
82	// the "task statuses out of the conversation logs" half of the census (owner,
83	// 2026-08-06). Same single-home rule: renderer and parser sit here together.
84	
85	export const TASK_EXEC_STATUSES = Object.freeze([
86	  // The dispatch ran to completion within its ceiling; the issue was closed.
87	  'success',
88	  // The run failed (task failure or ceiling violation); converged to needs-human.
89	  'failed',
90	  // The dispatch named a task the repo no longer carries (file gone, pack
91	  // undeclared) — the executor closed the issue as obsolete. Not a failure.
92	  'task-gone',
93	  // The dispatch was malformed (bad path shape, unparseable declaration) and was
94	  // converged to needs-human without running.
95	  'invalid',
96	]);
97	
98	export const TASK_EXEC_TAG = 'claudinite-task-exec';
99	
100	// The bracketed field is the OCCURRENCE'S IDENTITY, which is a different thing under
101	// each dispatch mechanism: a slot id (`d2026-08-06`) where slots decide what runs, and
102	// the work item's issue number (`#867`) where the queue does. `slotId` keeps its name
103	// for the fielded records that already carry one; what it must never become is a
104	// constant, since it is the only join from a record back to the work it describes.
105	export const renderTaskExec = ({ pack, task, slotId, status }) =>
106	  `${TASK_EXEC_TAG} ${VERSION} ${pack}/${task} [${slotId ?? 'unknown'}] ${status}`;
107	
108	const EXEC_LINE_RE = new RegExp(
109	  String.raw`(?:^|\s)${TASK_EXEC_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
110	);
111	
112	export function parseTaskExec(line) {
113	  const m = EXEC_LINE_RE.exec(line);
114	  if (!m) return null;
115	  const [, pack, task, slotId, status] = m;
116	  if (!TASK_EXEC_STATUSES.includes(status)) return null;
117	  return { pack, task, slotId, status };
118	}
119	
120	export function parseTaskExecs(text) {
121	  const out = [];
122	  for (const line of String(text ?? '').split('\n')) {
123	    const rec = parseTaskExec(line);
124	    if (rec) out.push(rec);
125	  }
126	  return out;
127	}

